export function wordsForCategories(ids: string[]): VocabWord[] {
  if (!ids.length) return VOCAB;
  const want = new Set(ids);
  return VOCAB.filter((w) => want.has(w.category));
}

/** Words that carry both clues — required for the clue→guess format. */
export function wordsWithClues(pool: VocabWord[]): VocabWord[] {
  return pool.filter((w) => w.fn && w.feat);
}
